Translate("frFR", "shadowfang-keep", {
	title = "Donjon d'Ombrecroc",
	aliases = { "Ombrecroc" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Donjon d'Ombrecroc se dresse sur une colline sombre au sud de la {link:silverpine-forest}Forêt des Pins argentés{/link}, au-dessus du hameau de {link:pyrewood-village}Bois-du-Bûcher{/link}. Ce fut jadis le siège du noble baron {link:baron-silverlaine}Silverlaine{/link}. C'est aujourd'hui l'antre de l'archimage {link:archmage-arugal}Arugal{/link} et des worgens qu'il appelle ses enfants. Des hommes-loups rôdent dans ses salles, des worgs hurlent dans ses cours, et les morts de la maisonnée du baron arpentent encore les pièces où ils furent tués.]=],
		},
		{
			title = "Origines",
			text = [=[Pendant la {link:third-war}Troisième Guerre{/link}, les sorciers du {link:kirin-tor}Kirin Tor{/link} combattirent le {link:scourge}Fléau{/link} dans le nord. Chaque sorcier qui tombait se relevait bientôt pour combattre au service de l'ennemi, et le Fléau ne cessait de grandir. {link:archmage-arugal}Arugal{/link} refusa de l'accepter. Contre l'avis de ses pairs, il fit appel à des êtres venus d'au-delà du monde pour combler les rangs clairsemés de {link:dalaran}Dalaran{/link}. Ce qui répondit à son appel, ce furent les {red:worgen}worgens{/red}. Les voraces hommes-loups taillèrent en pièces les morts-vivants, puis se retournèrent contre les sorciers eux-mêmes. Ils assiégèrent le donjon du baron {link:baron-silverlaine}Silverlaine{/link}, qui sombra dans l'ombre et la ruine. Rendu fou par la culpabilité, Arugal prit les worgens pour ses propres enfants. Il se retira dans le donjon déchu et lui donna un nouveau nom : Ombrecroc.]=],
		},
		{
			title = "De nos jours",
			text = [=[Les {link:forsaken}Réprouvés{/link} ne peuvent tenir la {link:silverpine-forest}Forêt des Pins argentés{/link} tant qu'{link:archmage-arugal}Arugal{/link} est en vie, et ils ont juré sa mort. Le grand exécuteur {link:high-executor-hadrec}Hadrec{/link} a envoyé deux Traqueurs noirs dans le donjon pour en percer les secrets. Ils ne sont pas revenus. Le {link:kirin-tor}Kirin Tor{/link} a lui aussi envoyé son propre agent, qui n'a pas eu plus de chance. Tous deux attendent désormais dans des cellules près de la porte. Le gardien {link:keeper-bel-dugur}Bel'dugur{/link}, de l'{link:undercity}Undercity{/link}, veut un livre qui se trouve quelque part dans le donjon, l'œuvre d'un mage de {link:dalaran}Dalaran{/link} nommé Ur, qui étudiait d'autres mondes. Au {link:the-sepulcher}Sépulcre{/link}, un archimage mort affirme désormais qu'Arugal n'a jamais créé les worgens.]=],
		},
		{
			title = "Dans le donjon",
			text = [=[• {b}Les cellules.{/b} Près de l'entrée, le worgen {link:rethilgore}Rethilgore{/link} garde ses prisonniers sous clé.
• {b}La cour.{/b} Au-delà d'une porte scellée s'étend la cour intérieure, où les soldats morts du donjon et les worgens d'{link:archmage-arugal}Arugal{/link} montent la garde ensemble.
• {b}Les salles de la maisonnée.{/b} {link:razorclaw-the-butcher}Razorclaw le Boucher{/link} travaille dans les cuisines. Le fantôme du baron {link:baron-silverlaine}Silverlaine{/link} hante la salle à manger, et le commandant {link:commander-springvale}Springvale{/link} tient une salle du conseil avec ses officiers morts.
• {b}Les hauteurs.{/b} {link:odo-the-blindwatcher}Odo the Blindwatcher{/link} tient son poste de guet en haut des murailles. Le maître-loup {link:wolf-master-nandos}Nandos{/link} mène sa meute à travers la cour supérieure, et {link:fenrus-the-devourer}Fenrus le Dévoreur{/link} garde les appartements de son maître.
• {b}Le refuge d'Arugal.{/b} Au sommet du donjon, l'archimage attend parmi ses serviteurs.]=],
		},
	},
})

Translate("frFR", "archmage-arugal", {
	title = "Archimage Arugal",
	subtitle = "Maître du Donjon d'Ombrecroc",
	found = "Les plus hautes salles du Donjon d'Ombrecroc",
	hint = [=[Apprenez son histoire au Sépulcre, ou montez au sommet du Donjon d'Ombrecroc.]=],
	allegiance = "Sons of Arugal · autrefois le Kirin Tor",
	aliases = { "Arugal" },
	sections = {
		{
			title = "Résumé",
			text = [=[Arugal était un archimage du {link:kirin-tor}Kirin Tor{/link} de {link:dalaran}Dalaran{/link}. Pendant la {link:third-war}Troisième Guerre{/link}, quand les sorciers de son ordre moururent et se relevèrent au service du {link:scourge}Fléau{/link}, il invoqua les {red:worgen}worgens{/red} pour combattre à leurs côtés. Les worgens massacrèrent les morts, puis se retournèrent contre les vivants. Rendu fou par la culpabilité, Arugal prit les bêtes pour ses fils, s'empara du donjon du baron {link:baron-silverlaine}Silverlaine{/link} et le nomma {link:shadowfang-keep}Donjon d'Ombrecroc{/link}. De là, sa malédiction s'est répandue dans toute la {link:silverpine-forest}Forêt des Pins argentés{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Arugal est la racine du fléau worgen dans la {link:silverpine-forest}Forêt des Pins argentés{/link}. Ses entraves lient les villageois de {link:pyrewood-village}Bois-du-Bûcher{/link}, sa magie a souillé les mineurs du gouffre d'Elem, et ses fils chassent sur les routes. Pour les {link:forsaken}Réprouvés{/link}, il est le dernier grand obstacle à leur emprise sur la forêt.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il séjourna d'abord dans une ferme à blé du nord de la {link:silverpine-forest}Forêt des Pins argentés{/link}, et y laissa ses grimoires.
• Il invoqua les worgens contre la volonté de ses pairs.
• Il maudit le village de {link:pyrewood-village}Bois-du-Bûcher{/link}, et le gouverne par l'entremise de son conseil.
• Il prit le donjon du baron {link:baron-silverlaine}Silverlaine{/link} et fit de ses morts sa maisonnée.
• Il garde une grande bête, {link:fenrus-the-devourer}Fenrus{/link}, et des serviteurs de l'ombre venus d'au-delà du monde.
• Au combat, il maudit ses ennemis en leur donnant la forme de worgens, et fait pleuvoir sur eux des traits du Vide et le tonnerre.]=],
		},
		{
			title = "Ce que l'on ignore",
			text = [=[Aucune chronique de ces jours ne rapporte la vie d'Arugal avant la {link:third-war}Troisième Guerre{/link}, ni d'où venaient vraiment ses worgens.]=],
		},
	},
	chapters = {
		{
			title = "Le remède",
			hint = [=[Récupérez le sort de l'archimage dans la ferme où il séjourna jadis.]=],
			text = [=[Parmi les livres qu'Arugal laissa à la ferme se trouvait un sort qu'il appelait son remède. {link:dalar-dawnweaver}Dalar Dawnweaver{/link}, qui avait connu le {link:kirin-tor}Kirin Tor{/link} de l'intérieur, le lut avec mépris. Il se demanda à voix haute comment un tel homme avait pu être admis dans l'ordre. Les sorts d'Arugal, dit-il, étaient si minces que n'importe quel apprenti pouvait voir au travers.]=],
		},
		{
			title = "Les entraves de Bois-du-Bûcher",
			hint = [=[Apportez les entraves de Bois-du-Bûcher à l'archimage mort du Sépulcre.]=],
			text = [=[Arugal compensait la faiblesse de sa magie par des objets enchantés. Chaque worgen des Moonrage portait son entrave, tout comme chaque villageois de {link:pyrewood-village}Bois-du-Bûcher{/link}, humain le jour et bête la nuit. De ces entraves, {link:dalar-dawnweaver}Dalar{/link} tira le pouvoir dont il avait besoin pour comprendre la malédiction.]=],
		},
		{
			title = "L'imposteur",
			hint = [=[Aidez l'archimage mort à prouver ses dires avec des restes pris au mur de Greymane.]=],
			text = [=[Avec le temps, {link:dalar-dawnweaver}Dalar{/link} parvint à un verdict que nul n'attendait. Les entraves prouvaient qu'Arugal pouvait lier les worgens. Elles ne prouvaient pas qu'il les avait créés. Sa célèbre malédiction était trop faible pour durer. Les worgens, dit Dalar, propageaient leur malédiction d'une autre manière.]=],
		},
		{
			title = "La mort d'Arugal",
			hint = [=[Montez au sommet du Donjon d'Ombrecroc et mettez fin aux sorts de l'archimage.]=],
			text = [=[{link:dalar-dawnweaver}Dalar{/link} refusait de laisser {link:sylvanas-windrunner}la Dame noire{/link} revendiquer la {link:silverpine-forest}Forêt des Pins argentés{/link} tant qu'Arugal vivait, et il réclama la tête de l'archimage. Au sommet de son donjon, parmi ses serviteurs et ses fils, Arugal fut tué. Sa tête fut rapportée au {link:the-sepulcher}Sépulcre{/link}.]=],
		},
	},
	mentions = {
		{ text = "La folie d'Arugal, le remède" },
		{ text = "La folie d'Arugal, les entraves" },
		{ text = "La folie d'Arugal, un nouveau verdict" },
		{ text = "Arrêter la propagation" },
		{ text = "Embuscade à {link:pyrewood-village}Bois-du-Bûcher{/link}" },
		{ text = "Arugal doit mourir" },
	},
	bonds = {
		{ id = "dalar-dawnweaver", name = "Dalar Dawnweaver", note = "le méprise" },
		{ id = "baron-silverlaine", name = "Baron Silverlaine", note = "hante son donjon" },
		{ id = "fenrus-the-devourer", name = "Fenrus le Dévoreur", note = "sa grande bête" },
		{ id = "pyrewood-villagers", name = "Villageois de Bois-du-Bûcher", note = "maudits par lui" },
		{ id = "apothecary-berard", name = "Apothicaire Berard", note = "a perdu la raison à cause de la malédiction" },
	},
})

Translate("frFR", "baron-silverlaine", {
	title = "Baron Silverlaine",
	subtitle = "Le fantôme vengeur",
	found = "La salle à manger du Donjon d'Ombrecroc",
	hint = [=[Cherchez le fantôme de l'ancien seigneur du donjon dans sa salle à manger.]=],
	allegiance = "Maison Silverlaine",
	aliases = { "Silverlaine" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le baron Silverlaine était le noble seigneur du donjon qui domine {link:pyrewood-village}Bois-du-Bûcher{/link}. Quand les worgens d'{link:archmage-arugal}Arugal{/link} vinrent, ils assiégèrent sa demeure, et elle tomba. Silverlaine mourut avec elle. Il ne trouva pas le repos. Son fantôme arpente la salle à manger où il festoyait jadis, parmi les serviteurs morts de sa maisonnée, et il tourne sa colère contre quiconque s'y introduit.]=],
		},
		{
			title = "Importance",
			text = [=[Silverlaine est la première victime de la folie d'{link:archmage-arugal}Arugal{/link} dans le donjon, et son maître légitime. Le donjon était le sien avant de devenir {link:shadowfang-keep}Ombrecroc{/link}. Il sombra vite dans l'ombre et la ruine, et les worgens qui le prirent rôdent aujourd'hui dans les pièces autour de sa salle. Son esprit vengeur rappelle que l'archimage a bâti son refuge sur les tombes d'autrui.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Son donjon fut assiégé par les worgens, et il tomba.
• Sa maisonnée mourut avec lui, et ses morts servent encore dans les salles.
• Dans la mort, il jette sur ses ennemis un voile d'ombre qui affaiblit tout soin.
• Il porte encore le sceau de sa famille.]=],
		},
		{
			title = "Ce que l'on ignore",
			text = [=[Aucune chronique de ces jours ne rapporte le prénom du baron, sa famille ni le seigneur qu'il servait. Il n'est pas écrit pourquoi son fantôme demeure quand tant d'autres sont partis.]=],
		},
	},
	chapters = {
		{
			title = "Le seigneur de la salle à manger",
			hint = "Affrontez le fantôme du baron dans sa propre salle.",
			text = [=[Les morts de la maisonnée sont encore liés au donjon. Serviteurs et gardes gémissent dans ses salles, et le baron marche parmi eux dans sa salle à manger. Il n'a pas pu tenir les worgens hors de sa maison. Depuis, il n'a pardonné à aucun de ceux qui y entrent.]=],
		},
	},
	mentions = {
		{ text = "{link:archmage-arugal}Arugal{/link} doit mourir" },
	},
	bonds = {
		{ id = "archmage-arugal", name = "Archimage Arugal", note = "a pris son donjon" },
		{ id = "commander-springvale", name = "Commandant Springvale", note = "commande ses soldats morts" },
	},
})

Translate("frFR", "commander-springvale", {
	title = "Commandant Springvale",
	subtitle = "Commandant de la garde morte",
	found = "Une salle du conseil du Donjon d'Ombrecroc",
	hint = [=[Affrontez le commandant mort qui tient encore son poste dans le donjon.]=],
	allegiance = "Maison Silverlaine",
	aliases = { "Springvale" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le commandant Springvale menait les soldats du baron {link:baron-silverlaine}Silverlaine{/link}. Quand les worgens prirent d'assaut le donjon, il tomba à son poste, et il se releva parmi ses morts. Il tient encore une salle du conseil avec ses officiers tourmentés, et les fantômes de ses gardes gémissent dans les salles autour de lui.]=],
		},
		{
			title = "Importance",
			text = [=[Springvale était de son vivant un serviteur de la {link:holy-light}Lumière sacrée{/link}, et la Lumière ne l'a pas tout à fait quitté. Il soigne encore ses blessures grâce à elle, s'en fait un bouclier et abat ses ennemis avec le marteau de la justice. C'est un spectacle amer : un défenseur du donjon, changé par la mort en un gardien de plus de l'antre d'{link:archmage-arugal}Arugal{/link}. Il n'est pas seul à partager ce sort. Des officiers tourmentés se tiennent à ses côtés, des gardes gémissants arpentent les salles, et des serviteurs hantés entretiennent encore les pièces d'un seigneur disparu.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il commandait les soldats du baron.
• Il mourut lors de la chute du donjon.
• Il monte encore la garde, avec ses officiers, sur des pièces qui n'appartiennent plus à son seigneur.]=],
		},
		{
			title = "Ce que l'on ignore",
			text = [=[Aucune chronique de ces jours ne rapporte le nom de Springvale avant le donjon, ni où il apprit à manier la Lumière.]=],
		},
	},
	chapters = {
		{
			title = "La dernière garde",
			hint = "Affrontez le commandant mort et ses officiers.",
			text = [=[Le donjon est tombé et son seigneur est mort. Springvale tient pourtant son poste, ses officiers à ses côtés. Quand des étrangers entrent, il invoque la Lumière contre eux, comme il le fit contre les worgens.]=],
		},
	},
	mentions = {
		{ text = "{link:archmage-arugal}Arugal{/link} doit mourir" },
	},
	bonds = {
		{ id = "baron-silverlaine", name = "Baron Silverlaine", note = "son seigneur" },
		{ id = "archmage-arugal", name = "Archimage Arugal", note = "maître du donjon pour lequel il mourut" },
	},
})

Translate("frFR", "rethilgore", {
