	},
	bonds = {
		{ id = "deathstalker-adamant", name = "Traqueur noir Adamant", note = "son prisonnier" },
		{ id = "sorcerer-ashcrombe", name = "Ensorceleur Ashcrombe", note = "son prisonnier" },
	},
})

