Translate("frFR", "wolf-master-nandos", {
	title = "Maître-loup Nandos",
	subtitle = "Maître de la meute",
	found = "La cour supérieure du Donjon d'Ombrecroc",
	hint = [=[Affrontez le worgen qui mène une meute de worgs dans la cour supérieure.]=],
	allegiance = "Sons of Arugal",
	aliases = { "Nandos" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le maître-loup Nandos est un worgen qui commande les meutes de loups d'{link:shadowfang-keep}Ombrecroc{/link}. Ses worgs et ses horreurs lupines parcourent la cour supérieure, et il peut en appeler d'autres d'un hurlement. Il aime sa meute. Quand elle est détruite, son chagrin devient fureur.]=],
		},
		{
			title = "Importance",
			text = [=[Nandos est le dernier des gardiens d'{link:archmage-arugal}Arugal{/link} avant l'archimage lui-même. De tous les Sons of Arugal, il est celui qui garde des bêtes à lui.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il appelle à ses côtés des worgs lugubres, des worgs baveux et des horreurs lupines.
• Il jure vengeance contre ceux qui tuent sa meute.]=],
		},
	},
	mentions = {
		{ text = "{link:archmage-arugal}Arugal{/link} doit mourir" },
